#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int a[24], n, n2, ans = 30, v[24];
bool d[1 << 24] = {true, true};

bool cmp(int x, int y) {
	return a[x] < a[y];
}

int main() {
	cin >> n;
	n++;

	for (int i = 1; i < n; i++)
		cin >> a[i];

	n2 = 1 << n;
	d[2] = d[3] = true;

	for (int i = 2; i < n2; i++) {
		if (d[i]) {
			int l = 0;

			for (int j = 1, k = 0; j <= i; j <<= 1, k++)
				if (i & j)
					v[l++] = k;

			int t = v[l - 1] + 1;

			if (t == n) {
				ans = min(ans, l);
			} else {
				sort(v, v + l, cmp);

				for (int j = 0, k = l - 1; j < l && k >= 0;) {
					int sum = a[v[j]] + a[v[k]];

					if (sum == a[t]) {
						int h = i + (1 << t);
						d[h] = true;

						for (int c = 0; c < l; c++)
							d[h - (1 << v[c])] = true;

						break;
					}

					if (sum < a[t])
						j++;
					else
						k--;
				}
			}
		}
	}

	cout << (ans == 30 ? -1 : ans) << '\n';
	return 0;
}

